module.exports = [{"id_kalimat":"amogenz_kalimat_004","teks_kalimat":"فكيف تنكر حبا","analysis":[{"id_lafadz":"amogenz_lafadz_013","word":"ف","steps":{"1":{"question":"Apa jenis Lafadz ف?","options":["Isim","Fi'il","Huruf"],"correct":"Huruf","explanation":"Lafadz 'Fa' di sini adalah Huruf Isti'nafiyah (permulaan) atau Athaf yang tidak memiliki tanda-tanda isim maupun fi'il."},"2":{"question":"Apa tanda/alasan lafadz ف disebut Huruf?","options":["Tidak menerima tanda Isim dan Fi'il","Kemasukan Tanwin","Dapat di-I'rob Rafa'"],"correct":"Tidak menerima tanda Isim dan Fi'il","explanation":"Kriteria huruf adalah kalimat yang tidak layak menerima tanda-tanda khusus isim (seperti Al dan Tanwin) maupun tanda fi'il (seperti Qad dan Ta' Fa'il)."},"3":{"question":"Apa nadhom/syahidnya lafadz ف disebut Huruf?","options":["بالجر والتنوين والندا وأل || ومسند للاسم تمييز حصل","بتا فعلت وأتت ويا افعلي || ونون أقبلن فعل ينجلي","سواهما الحرف كهل وفي ولم || فعل مضارع يلي لم كيشم"],"correct":"سواهما الحرف كهل وفي ولم || فعل مضارع يلي لم كيشم","explanation":"Bait ini menjelaskan bahwa huruf adalah kata yang tidak menerima tanda isim dan fi'il, contohnya hal, fi, dan lam."},"4":{"question":"Status lafadz ف itu Mu'rob atau Mabni?","options":["Mu'rob","Mabni"],"correct":"Mabni","explanation":"Seluruh jenis huruf dalam gramatika Arab dihukumi Mabni (statis/tidak berubah akhirnya)."},"5":{"question":"Mengapa lafadz ف berstatus Mabni?","options":["Karena semua huruf wajib Mabni","Karena menyerupai Isim","Karena tidak ada Amil"],"correct":"Karena semua huruf wajib Mabni","explanation":"Kaidah dasar Nahwu menyatakan bahwa huruf tidak memiliki asal mu'rob, sehingga ia menetap pada satu keadaan."},"6":{"question":"Apa nadhom/syahidnya lafadz ف disebut Mabni?","options":["وكل حرف مستحق للبنا || والأصل في المبني أن يسكنا","والاسم منه معرب ومبني || لشبه من الحروف مدني","ومعرب الأسماء ما قد سلما || من شبه الحرف كأرض وسما"],"correct":"وكل حرف مستحق للبنا || والأصل في المبني أن يسكنا","explanation":"Bait ini menegaskan bahwa setiap huruf berhak (mustahiq) atas hukum Mabni."},"7":{"question":"Apa kedudukan Mabni 'ala lafadz ف?","options":["Mabni 'ala al-Fath","Mabni 'ala ad-Dhomm","Mabni 'ala as-Sukun"],"correct":"Mabni 'ala al-Fath","explanation":"Lafadz 'Fa' dibaca dengan harakat fathah secara tetap di mana pun posisinya."},"8":{"question":"Apa alasan lafadz ف dihukumi Mabni 'ala al-Fath?","options":["Karena merupakan harakat asli pada huruf satu unit","Sesuai pendengaran (Sima'i)","Karena mengikuti kata setelahnya"],"correct":"Sesuai pendengaran (Sima'i)","explanation":"Penentuan harakat mabni pada huruf didasarkan pada cara orang Arab mengucapkannya (Sima'i)."},"9":{"question":"Apa nadhom/syahidnya lafadz ف disebut Mabni 'ala al-Fath?","options":["ومنه ذو فتح وذو كسر وضم || كأين أمس حيث والساكن كم","فارفع بضم وانصبن فتحا وجر || كسرا كذكر الله عبده يسر","وكل حرف مستحق للبنا || والأصل في المبني أن يسكنا"],"correct":"ومنه ذو فتح وذو كسر وضم || كأين أمس حيث والساكن كم","explanation":"Bait ini merinci jenis-jenis bina/mabni, termasuk mabni fathah (Dzu Fathin) seperti pada kata 'Aina'."},"10":{"question":"Apa Mahal I'rob pada lafadz ف?","options":["Mahal Rafa'","Mahal Nashab","La Mahalla Lahu (Tidak memiliki mahal)"],"correct":"La Mahalla Lahu (Tidak memiliki mahal)","explanation":"Huruf-huruf seperti Fa' Isti'nafiyah tidak menduduki posisi i'rob dalam susunan kalimat."},"11":{"question":"Mengapa lafadz ف tandanya menggunakan La Mahalla Lahu?","options":["Karena ia bukan merupakan unsur pokok kalimat","Karena ia Isim","Karena ia Fi'il"],"correct":"Karena ia bukan merupakan unsur pokok kalimat","explanation":"Huruf hanya berfungsi sebagai penghubung atau penegas makna tanpa menduduki posisi jabatan kata (Mubtada, Fa'il, dll)."},"12":{"question":"apa nadzom/syahidnya lafadz ف itu tidak memiliki mahal?","options":["وكل حرف مستحق للبنا || والأصل في المبني أن يسكنا","والرفع والنصب اجعلن إعرابا || لاسم وفعل نحو لن أهابا","فارفع بضم وانصبن فتحا وجر || كسرا كذكر الله عبده يسر"],"correct":"وكل حرف مستحق للبنا || والأصل في المبني أن يسكنا","explanation":"Kewajiban bina pada huruf berimplikasi pada ketiadaan mahal i'rob kecuali pada huruf-huruf tertentu yang memiliki fungsi amil."}}},{"id_lafadz":"amogenz_lafadz_014","word":"كيف","steps":{"1":{"question":"Apa jenis Lafadz كيف?","options":["Isim","Fi'il","Huruf"],"correct":"Isim","explanation":"Kaifa adalah Isim Istifham (kata tanya) karena ia menempati posisi Musnad Ilaih atau Musnad dalam kalimat."},"2":{"question":"Apa tanda/alasan lafadz كيف disebut Isim?","options":["Bisa menjadi Musnad (sebagai Khabar atau Haal)","Kemasukan Al","Kemasukan Tanwin"],"correct":"Bisa menjadi Musnad (sebagai Khabar atau Haal)","explanation":"Meskipun tidak menerima Al atau Tanwin, Kaifa memiliki makna yang dapat di-isnad-kan (diberi sandaran makna)."},"3":{"question":"Apa nadhom/syahidnya lafadz كيف disebut Isim?","options":["بالجر والتنوين والندا وأل || ومسند للاسم تمييز حصل","بتا فعلت وأتت ويا افعلي || ونون أقبلن فعل ينجلي","سواهما الحرف كهل وفي ولم || فعل مضارع يلي لم كيشم"],"correct":"بالجر والتنوين والندا وأل || ومسند للاسم تمييز حصل","explanation":"Syahid untuk Isnad (Musnad) sebagai tanda isim yang paling mencakup banyak lafadz."},"4":{"question":"Status lafadz كيف itu Mu'rob atau Mabni?","options":["Mu'rob","Mabni"],"correct":"Mabni","explanation":"Isim Istifham dihukumi Mabni karena ia menyerupai Huruf Istifham dalam hal maknanya (Syabah Ma'nawi)."},"5":{"question":"Mengapa lafadz كيف berstatus Mabni?","options":["Menyerupai Huruf (Syabah Ma'nawi)","Karena ia isim alam","Karena kemasukan amil"],"correct":"Menyerupai Huruf (Syabah Ma'nawi)","explanation":"Kaifa membawa makna tanya, di mana makna tanya seharusnya dimiliki oleh huruf (seperti Hamzah Istifham)."},"6":{"question":"Apa nadhom/syahidnya lafadz كيف disebut Mabni?","options":["كالشبه الوضعي في اسمي جئتنا || والمعنوي في متى وفي هنا","والاسم منه معرب ومبني || لشبه من الحروف مدني","وكل حرف مستحق للبنا || والأصل في المبني أن يسكنا"],"correct":"كالشبه الوضعي في اسمي جئتنا || والمعنوي في متى وفي هنا","explanation":"Bait ini menyebutkan Syabah Ma'nawi (seperti Mata dan Huna/Kaifa) sebagai sebab kemabnian isim."},"7":{"question":"Apa kedudukan I'rob/Mabni lafadz كيف?","options":["Nashab","Rafa'","Jazm"],"correct":"Nashab","explanation":"Kaifa di sini menduduki tempat (Mahal) Nashab karena menjadi Haal (penjelas keadaan) bagi pelaku fi'il setelahnya."},"8":{"question":"Apa alasan lafadz كيف dihukumi Nashab?","options":["Sebagai Haal","Sebagai Maf'ul Bih","Sebagai Mubtada"],"correct":"Sebagai Haal","explanation":"Karena setelah Kaifa terdapat fi'il taam (tunkiru), maka ia berfungsi menjelaskan keadaan subjek saat melakukan pengingkaran."},"9":{"question":"Apa nadhom/syahidnya lafadz كيف disebut Haal?","options":["الحال وصف فضلة منتصب || مفهم في حال كفردا أذهب","فانصب به المفعول إن لم ينب || عن فاعل نحو تدبرت الكتبي","ورفعوا مبتدأ بالابتدا || كذاك رفع خبر بالمبتدا"],"correct":"الحال وصف فضلة منتصب || مفهم في حال كفردا أذهب","explanation":"Nadzom ini mendefinisikan Haal sebagai sifat pelengkap yang dibaca nashab."},"10":{"question":"Apa tanda I'rob/Mahal I'rob pada lafadz كيف?","options":["Fathah (Mabni)","Sukun","Kasrah"],"correct":"Fathah (Mabni)","explanation":"Lafadz Kaifa diakhiri dengan harakat fathah secara tetap (Mabni 'ala al-Fath)."},"11":{"question":"Mengapa lafadz كيف tandanya menggunakan Fathah (Mabni)?","options":["Sesuai kaidah Sima'i pada isim mabni","Karena ia isim mufrad","Karena ia mu'rob"],"correct":"Sesuai kaidah Sima'i pada isim mabni","explanation":"Harakat fathah pada Kaifa adalah permanen berdasarkan aturan pembentukan kata tanya tersebut."},"12":{"question":"apa nadzom/syahidnya lafadz كيف itu tandanya menggunakan Fathah (Mabni)?","options":["ومنه ذو فتح وذو كسر وضم || كأين أمس حيث والساكن كم","فارفع بضم وانصبن فتحا وجر || كسرا كذكر الله عبده يسر","وكل حرف مستحق للبنا || والأصل في المبني أن يسكنا"],"correct":"ومنه ذو فتح وذو كسر وضم || كأين أمس حيث والساكن كم","explanation":"Syahid untuk lafadz yang dimabnikan atas fathah (Dzu Fathin)."}}},{"id_lafadz":"amogenz_lafadz_015","word":"تنكر","steps":{"1":{"question":"Apa jenis Lafadz تنكر?","options":["Isim","Fi'il","Huruf"],"correct":"Fi'il","explanation":"Lafadz 'Tunkiru' adalah Fi'il Mudhari karena menunjukkan perbuatan yang sedang berlangsung dan diawali huruf mudhara'ah."},"2":{"question":"Apa tanda/alasan lafadz تنكر disebut Fi'il?","options":["Diawali huruf Mudhara'ah (Ta') dan bisa kemasukan 'Lam'","Kemasukan Tanwin","Kemasukan Al"],"correct":"Diawali huruf Mudhara'ah (Ta') dan bisa kemasukan 'Lam'","explanation":"Salah satu ciri utama fi'il mudhari adalah kelayakannya mengikuti huruf 'Lam' (Lam Yalid)."},"3":{"question":"Apa nadhom/syahidnya lafadz تنكر disebut Fi'il?","options":["سواهما الحرف كهل وفي ولم || فعل مضارع يلي لم كيشم","بتا فعلت وأتت ويا افعلي || ونون أقبلن فعل ينجلي","بالجر والتنوين والندا وأل || ومسند للاسم تمييز حصل"],"correct":"سواهما الحرف كهل وفي ولم || فعل مضارع يلي لم كيشم","explanation":"Nadzom ini menerangkan bahwa ciri fi'il mudhari adalah bisa diawali oleh Lam."},"4":{"question":"Status lafadz تنكر itu Mu'rob atau Mabni?","options":["Mu'rob","Mabni"],"correct":"Mu'rob","explanation":"Fi'il mudhari dihukumi mu'rob selama tidak bersambung dengan Nun Taukid atau Nun Inats secara langsung."},"5":{"question":"Mengapa lafadz تنكر berstatus Mu'rob?","options":["Karena tidak bersambung dengan Nun Taukid/Inats","Karena diawali huruf mudhara'ah","Karena ia fi'il madhi"],"correct":"Karena tidak bersambung dengan Nun Taukid/Inats","explanation":"Kesunyian fi'il mudhari dari dua jenis Nun tersebut menjadikannya mu'rob (berubah harakat akhirnya)."},"6":{"question":"Apa nadhom/syahidnya lafadz تنكر disebut Mu'rob?","options":["وفعل أمر ومضي بنيا || وأعربوا مضارعا إن عريا","والاسم منه معرب ومبني || لشبه من الحروف مدني","وكل حرف مستحق للبنا || والأصل في المبني أن يسكنا"],"correct":"وفعل أمر ومضي بنيا || وأعربوا مضارعا إن عريا","explanation":"Bait ini menjelaskan bahwa fi'il mudhari dihukumi mu'rob jika sepi (ariya) dari nun penguat dan nun perempuan."},"7":{"question":"Apa kedudukan I'rob/Mabni lafadz تنكر?","options":["Rafa'","Nashab","Jazm"],"correct":"Rafa'","explanation":"Fi'il mudhari dibaca rafa' jika tidak didahului oleh amil nashab (seperti An, Lan) maupun amil jazm (seperti Lam, Laa)."},"8":{"question":"Apa alasan lafadz تنكر dihukumi Rafa'?","options":["Tajarrud (Sepi dari amil nashab dan jazm)","Sebagai Fa'il","Sebagai Khabar"],"correct":"Tajarrud (Sepi dari amil nashab dan jazm)","explanation":"Alasan i'rob rafa' pada fi'il mudhari adalah karena posisinya yang kosong dari faktor-faktor yang merubahnya menjadi nashab atau jazm."},"9":{"question":"Apa nadhom/syahidnya lafadz تنكر disebut Rafa'?","options":["ارفع مضارعا إذا يجرد || من ناصب وجازم كتسعد","والرفع والنصب اجعلن إعرابا || لاسم وفعل نحو لن أهابا","وحذفها للجزم حكم واجبا || كقد رأيت قاضيا ومفتيا"],"correct":"ارفع مضارعا jika yujarrad || min naashibin wa jaazimin katus'ad","explanation":"Nadzom ini secara jelas memerintahkan merofa'kan mudhari jika kosong dari nashab dan jazm."},"10":{"question":"Apa tanda I'rob/Mahal I'rob pada lafadz تنكر?","options":["Dhammah","Fathah","Sukun"],"correct":"Dhammah","explanation":"Tanda rafa' asli untuk fi'il mudhari yang bukan merupakan Af'alul Khomsah adalah dhammah."},"11":{"question":"Mengapa lafadz تنكر tandanya menggunakan Dhammah?","options":["Karena Fi'il Mudhari Shahih Akhir","Karena Isim Mufrad","Karena Fi'il Mu'tal Akhir"],"correct":"Karena Fi'il Mudhari Shahih Akhir","explanation":"Huruf terakhirnya (Ra') adalah huruf shahih, bukan Alif, Wawu, atau Ya', sehingga menerima harakat dhammah secara zhohir (nampak)."},"12":{"question":"apa nadzom/syahidnya lafadz تنكر itu tandanya menggunakan Dhammah?","options":["فارفع بضم وانصبن فتحا وجر || كسرا كذكر الله عبده يسر","والرفع والنصب اجعلن إعرابا || لاسم وفعل نحو لن أهابا","اجعل لنحو يفعلان نونا || رفعهما وتدعين وتسالونا"],"correct":"فارفع بضم وانصبن فتحا وجر || كسرا كذكر الله عبده يسر","explanation":"Bait ini menjelaskan tanda rafa' asli adalah dhammah (irfa' bidhommin)."}}},{"id_lafadz":"amogenz_lafadz_016","word":"حبا","steps":{"1":{"question":"Apa jenis Lafadz حبا?","options":["Isim","Fi'il","Huruf"],"correct":"Isim","explanation":"Lafadz 'Hubban' adalah isim karena menunjukkan makna benda (cinta/perasaan) dan menerima tanda tanwin."},"2":{"question":"Apa tanda/alasan lafadz حبا disebut Isim?","options":["Adanya Tanwin","Kemasukan Al","Adanya Huruf Mudhara'ah"],"correct":"Adanya Tanwin","explanation":"Harakat ganda (fathatain) di akhir kata merupakan ciri khas yang membedakan isim dari fi'il dan huruf."},"3":{"question":"Apa nadhom/syahidnya lafadz حبا disebut Isim?","options":["بالجر والتنوين والندا وأل || ومسند للاسم تمييز حصل","بتا فعلت وأتت ويا افعلي || ونون أقبلن فعل ينجلي","سواهما الحرف كهل وفي ولم || فعل مضارع يلي لم كيشم"],"correct":"بالجر والتنوين والندا وأل || ومسند للاسم تمييز حصل","explanation":"Nadzom ini merinci tanda-tanda isim: Jar, Tanwin, Nida, Al, dan Isnad."},"4":{"question":"Status lafadz حبا itu Mu'rob atau Mabni?","options":["Mu'rob","Mabni"],"correct":"Mu'rob","explanation":"Isim ini mu'rob karena tidak menyerupai huruf dalam segi mana pun."},"5":{"question":"Mengapa lafadz حبا berstatus Mu'rob?","options":["Selamat dari penyerupaan dengan huruf (Asal isim)","Karena berharakat tanwin","Karena ia Isim Mashdar"],"correct":"Selamat dari penyerupaan dengan huruf (Asal isim)","explanation":"Hukum asal isim adalah mu'rob, kecuali jika ada kemiripan dengan huruf yang menjadikannya mabni."},"6":{"question":"Apa nadhom/syahidnya lafadz حبا disebut Mu'rob?","options":["ومعرب الأسماء ما قد سلما || من شبه الحرف كأرض وسما","والاسم منه معرب ومبني || لشبه من الحروف مدني","وكل حرف مستحق للبنا || والأصل في المبني أن يسكنا"],"correct":"ومعرب الأسماء ما قد سلما || من شبه الحرف كأرض وسما","explanation":"Nadzom ini menjelaskan bahwa isim mu'rob adalah isim yang selamat dari keserupaan dengan huruf."},"7":{"question":"Apa kedudukan I'rob/Mabni lafadz حبا?","options":["Nashab","Rafa'","Jarr"],"correct":"Nashab","explanation":"Lafadz 'Hubban' berkedudukan sebagai Maf'ul Bih (Objek) bagi fi'il 'Tunkiru'."},"8":{"question":"Apa alasan lafadz حبا dihukumi Nashab?","options":["Sebagai Maf'ul Bih","Sebagai Tamyiz","Sebagai Fa'il"],"correct":"Sebagai Maf'ul Bih","explanation":"Sesuatu yang menjadi sasaran dari perbuatan 'pengingkaran' (tunkiru) disebut Maf'ul Bih, dan hukumnya adalah nashab."},"9":{"question":"Apa nadhom/syahidnya lafadz حبا disebut Nashab?","options":["فانصب به المفعول إن لم ينب || عن فاعل نحو تدبرت الكتبي","الفاعل الذي كمرفوعي أتى || زيد منيرا وجهه نعم الفتى","فارفع بضم وانصبن فتحا وجر || كسرا كذكر الله عبده يسر"],"correct":"فانصب به المفعول إن لم ينب || عن فاعل نحو تدبرت الكتبي","explanation":"Bait ini memerintahkan untuk menashabkan maf'ul bih."},"10":{"question":"Apa tanda I'rob/Mahal I'rob pada lafadz حبا?","options":["Fathah","Dhammah","Kasrah"],"correct":"Fathah","explanation":"Tanda nashab asli bagi isim mufrad adalah fathah."},"11":{"question":"Mengapa lafadz حبا tandanya menggunakan Fathah?","options":["Karena Isim Mufrad","Karena Jamak Mudzakkar Salim","Karena Asmaul Khomsah"],"correct":"Karena Isim Mufrad","explanation":"Lafadz 'Hubban' bukan merupakan jamak maupun mutsanna, melainkan isim tunggal (mufrad)."},"12":{"question":"apa nadzom/syahidnya lafadz حبا itu tandanya menggunakan Fathah?","options":["فارفع بضم وانصبن فتحا وجر || كسرا كذكر الله عبده يسر","والرفع والنصب اجعلن إعرابا || لاسم وفعل نحو لن أهابا","بالألف ارفع المثنى وكلا || إذا بمضمر مضافا وصلا"],"correct":"فارفع بضم وانصبن فتحا وجر || كسرا كذكر الله عبده يسر","explanation":"Menjelaskan bahwa tanda nashab asli adalah fathah (wanshiban fatha)."}}}]},{"id_kalimat":"amogenz_kalimat_005","teks_kalimat":"لن تركع امة قائدها محمد","analysis":[{"id_lafadz":"amogenz_lafadz_017","word":"لن","steps":{"1":{"question":"Apa jenis Lafadz لن?","options":["Isim","Fi'il","Huruf"],"correct":"Huruf","explanation":"Lafadz 'Lan' adalah Huruf (Nafyi & Nashab) karena tidak menerima tanda-tanda khusus isim maupun fi'il."},"2":{"question":"Apa tanda/alasan lafadz لن disebut Huruf?","options":["Tidak menerima tanda Isim dan Fi'il","Kemasukan Al","Menerima Tanwin"],"correct":"Tidak menerima tanda Isim dan Fi'il","explanation":"Huruf didefinisikan sebagai kata yang tidak memiliki kecocokan dengan ciri-ciri isim (seperti jar) maupun fi'il (seperti ta' fail)."},"3":{"question":"Apa nadhom/syahidnya lafadz لن disebut Huruf?","options":["بالجر والتنوين والندا وأل || ومسند للاسم تمييز حصل","بتا فعلت وأتت ويا افعلي || ونون أقبلن فعل ينجلي","سواهما الحرف كهل وفي ولم || فعل مضارع يلي لم كيشم"],"correct":"سواهما الحرف كهل وفي ولم || فعل مضارع يلي لم كيشم","explanation":"Nadzom ini menjelaskan bahwa selain isim dan fi'il adalah huruf, seperti hal, fi, dan lam."},"4":{"question":"Status lafadz لن itu Mu'rob atau Mabni?","options":["Mu'rob","Mabni"],"correct":"Mabni","explanation":"Seluruh jenis huruf dalam bahasa Arab dihukumi Mabni (statis)."},"5":{"question":"Mengapa lafadz لن berstatus Mabni?","options":["Karena semua huruf wajib Mabni","Karena ia amil nashab","Karena menyerupai isim"],"correct":"Karena semua huruf wajib Mabni","explanation":"Sudah menjadi kaidah paten bahwa setiap huruf berhak atas kemabnian."},"6":{"question":"Apa nadhom/syahidnya lafadz لن disebut Mabni?","options":["وكل حرف مستحق للبنا || والأصل في المبني أن يسكنا","والاسم منه معرب ومبني || لشبه من الحروف مدني","ومعرب الأسماء ما قد سلما || من شبه الحرف كأرض وسما"],"correct":"وكل حرف مستحق للبنا || والأصل في المبني أن يسكنا","explanation":"Bait ini menegaskan bahwa setiap huruf wajib mabni dan asalnya mabni adalah sukun."},"7":{"question":"Apa kedudukan I'rob/Mabni lafadz لن?","options":["La Mahalla Lahu (Mabni)","Mahal Rafa'","Mahal Nashab"],"correct":"La Mahalla Lahu (Mabni)","explanation":"Sebagai huruf, ia tidak memiliki kedudukan (mahal) i'rob dalam jabatan kalimat (seperti fail/mubtada)."},"8":{"question":"Apa alasan lafadz لن dihukumi La Mahalla Lahu?","options":["Karena ia Huruf","Karena ia Amil Nashab","Karena ia Mabni"],"correct":"Karena ia Huruf","explanation":"Huruf secara fungsional hanya bekerja pada kata lain dan tidak menempati posisi jabatan kata."},"9":{"question":"Apa nadhom/syahidnya lafadz لن disebut Huruf Nashab?","options":["بلن نصبت وكي كذا بأن || لا بعد علم والتي كأن","وبين لا ولازم اضطرار || نال عمل في غير ما اضطرار","والرفع والنصب اجعلن إعرابا || لاسم وفعل نحو لن أهابا"],"correct":"بلن نصبت وكي كذا بأن || لا بعد علم والتي كأن","explanation":"Nadzom ini menyebutkan 'Lan' sebagai salah satu alat penashab fi'il mudhari."},"10":{"question":"Apa tanda Mabni pada lafadz لن?","options":["Mabni 'ala as-Sukun","Mabni 'ala al-Fath","Mabni 'ala ad-Dhomm"],"correct":"Mabni 'ala as-Sukun","explanation":"Lafadz 'Lan' diakhiri dengan huruf mati (Sukun) di atas Alif-nya."},"11":{"question":"Mengapa lafadz لن tandanya menggunakan Sukun?","options":["Karena asal kemabnian adalah sukun","Karena ia Isim","Karena ia Fi'il"],"correct":"Karena asal kemabnian adalah sukun","explanation":"Sesuai kaidah: Al-ashlu fil mabniyyi an yusakana."},"12":{"question":"apa nadzom/syahidnya lafadz لن itu tandanya menggunakan Sukun?","options":["وكل حرف مستحق للبنا || والأصل في المبني أن يسكنا","ومنه ذو فتح وذو كسر وضم || كأين أمس حيث والساكن كم","فارفع بضم وانصبن فتحا وجر || كسرا كذكر الله عبده يسر"],"correct":"وكل حرف مستحق للبنا || والأصل في المبني أن يسكنا","explanation":"Bait ini menjelaskan bahwa asal dari setiap yang mabni adalah sukun."}}},{"id_lafadz":"amogenz_lafadz_018","word":"تركع","steps":{"1":{"question":"Apa jenis Lafadz تركع?","options":["Isim","Fi'il","Huruf"],"correct":"Fi'il","explanation":"Lafadz 'Tark'a' adalah Fi'il Mudhari karena diawali huruf mudhara'ah 'Ta' dan menunjukkan waktu sekarang/akan datang."},"2":{"question":"Apa tanda/alasan lafadz تركع disebut Fi'il?","options":["Diawali huruf Mudhara'ah dan bisa kemasukan 'Lan'","Kemasukan Al","Kemasukan Tanwin"],"correct":"Diawali huruf Mudhara'ah dan bisa kemasukan 'Lan'","explanation":"Ciri khas mudhari adalah dapat dimasuki amil seperti 'Lan' atau 'Lam'."},"3":{"question":"Apa nadhom/syahidnya lafadz تركع disebut Fi'il?","options":["سواهما الحرف كهل وفي ولم || فعل مضارع يلي لم كيشم","بتا فعلت وأتت ويا افعلي || ونون أقبلن فعل ينجلي","بالجر والتنوين والندا وأل || ومسند للاسم تمييز حصل"],"correct":"سواهما الحرف كهل وفي ولم || فعل مضارع يلي لم كيشم","explanation":"Bait ini menegaskan bahwa mudhari adalah yang bisa dimasuki 'Lam' (atau amil sejenisnya)."},"4":{"question":"Status lafadz تركع itu Mu'rob atau Mabni?","options":["Mu'rob","Mabni"],"correct":"Mu'rob","explanation":"Fi'il Mudhari di sini mu'rob karena tidak bersambung dengan Nun Inats maupun Nun Taukid."},"5":{"question":"Mengapa lafadz تركع berstatus Mu'rob?","options":["Kosong dari Nun Taukid dan Nun Inats","Karena ia Fi'il Mudhari","Karena kemasukan amil nashab"],"correct":"Kosong dari Nun Taukid dan Nun Inats","explanation":"Mudhari hanya mabni jika bersambung dengan nun-nun tersebut secara langsung."},"6":{"question":"Apa nadhom/syahidnya lafadz تركع disebut Mu'rob?","options":["وفعل أمر ومضي بنيا || وأعربوا مضارعا إن عريا","وأعربوا مضارعا إن عريا || من نون توكيد مباشر ومن || نون إناث كيرعن من فتن","والاسم منه معرب ومبني || لشبه من الحروف مدني"],"correct":"وأعربوا مضارعا إن عريا || من نون توكيد مباشر ومن || نون إناث كيرعن من ften","explanation":"Bait ini merinci bahwa mudhari dihukumi mu'rob selama sepi (ariya) dari nun taukid dan nun inats."},"7":{"question":"Apa kedudukan I'rob lafadz تركع?","options":["Nashab","Rafa'","Jazm"],"correct":"Nashab","explanation":"Fi'il ini dibaca Nashab karena didahului oleh amil nashab yaitu 'Lan'."},"8":{"question":"Apa alasan lafadz تركع dihukumi Nashab?","options":["Didahului oleh Amil 'Lan'","Sebagai Fa'il","Sebagai Khabar"],"correct":"Didahului oleh Amil 'Lan'","explanation":"'Lan' adalah salah satu dari empat amil penashab fi'il mudhari yang asli."},"9":{"question":"Apa nadhom/syahidnya lafadz تركع disebut Nashab?","options":["بلن نصبت وكي كذا بأن || لا بعد علم والتي كأن","ارفع مضارعا إذا يجرد || من ناصب وجازم كتسعد","والرفع والنصب اجعلن إعرابا || لاسم وفعل نحو لن أهابا"],"correct":"بلن نصبت وكي كذا بأن || لا بعد علم والتي كأن","explanation":"Menyebutkan 'Lan' sebagai penashab (bin lan nashabta)."},"10":{"question":"Apa tanda I'rob pada lafadz تركع?","options":["Fathah","Dhammah","Sukun"],"correct":"Fathah","explanation":"Tanda nashab asli bagi fi'il mudhari shahih akhir adalah fathah."},"11":{"question":"Mengapa lafadz تركع tandanya menggunakan Fathah?","options":["Karena Fi'il Mudhari Shahih Akhir","Karena Isim Mufrad","Karena Fi'il Madhi"],"correct":"Karena Fi'il Mudhari Shahih Akhir","explanation":"Huruf akhirnya adalah 'Ain' yang merupakan huruf shahih (bukan huruf illat)."},"12":{"question":"apa nadzom/syahidnya lafadz تركع itu tandanya menggunakan Fathah?","options":["فارفع بضم وانصبن فتحا وجر || كسرا كذكر الله عبده يسر","والرفع والنصب اجعلن إعرابا || لاسم وفعل نحو لن أهابا","اجعل لنحو يفعلان نونا || رفعهما وتدعين وتسالونا"],"correct":"فارفع بضم وانصبن فتحا وجر || كسرا كذكر الله عبده يسر","explanation":"Bait ini menjelaskan tanda i'rob asli: dhommah untuk rafa', fathah untuk nashab."}}},{"id_lafadz":"amogenz_lafadz_019","word":"امة","steps":{"1":{"question":"Apa jenis Lafadz امة?","options":["Isim","Fi'il","Huruf"],"correct":"Isim","explanation":"Lafadz 'Ummatun' adalah Isim karena menunjukkan makna benda (sekumpulan orang) dan menerima tanwin."},"2":{"question":"Apa tanda/alasan lafadz امة disebut Isim?","options":["Adanya Tanwin","Kemasukan Al","Diawali Huruf Mudhara'ah"],"correct":"Adanya Tanwin","explanation":"Harakat ganda (tanwin) di akhir kata adalah ciri eksklusif isim."},"3":{"question":"Apa nadhom/syahidnya lafadz امة disebut Isim?","options":["بالجر والتنوين والندا وأل || ومسند للاسم تمييز حصل","بتا فعلت وأتت ويا افعلي || ونون أقبلن فعل ينجلي","سواهما الحرف كهل وفي ولم || فعل مضارع يلي لم كيشم"],"correct":"بالجر والتنوين والندا وأل || ومسند للاسم تمييز حصل","explanation":"Nadzom ini merinci ciri isim, salah satunya adalah tanwin."},"4":{"question":"Status lafadz امة itu Mu'rob atau Mabni?","options":["Mu'rob","Mabni"],"correct":"Mu'rob","explanation":"Isim ini mu'rob karena tidak menyerupai huruf dan harakat akhirnya berubah."},"5":{"question":"Mengapa lafadz امة berstatus Mu'rob?","options":["Selamat dari penyerupaan dengan huruf","Karena Isim Mufrad","Karena ia Fa'il"],"correct":"Selamat dari penyerupaan dengan huruf","explanation":"Hukum asal isim adalah mu'rob selama tidak memiliki 'illat kemabnian."},"6":{"question":"Apa nadhom/syahidnya lafadz امة disebut Mu'rob?","options":["ومعرب الأسماء ما قد سلما || من شبه الحرف كأرض وسما","والاسم منه معرب ومبني || لشبه من الحروف مدني","وكل حرف مستحق للبنا || والأصل في المبني أن يسكنا"],"correct":"ومعرب الأسماء ما قد سلما || من شبه الحرف كأرض وسما","explanation":"Nadzom ini menjelaskan isim mu'rob adalah yang selamat dari keserupaan dengan huruf."},"7":{"question":"Apa kedudukan I'rob lafadz امة?","options":["Rafa'","Nashab","Jarr"],"correct":"Rafa'","explanation":"Lafadz 'Ummatun' berkedudukan sebagai Fa'il (pelaku) dari fi'il 'Tark'a'."},"8":{"question":"Apa alasan lafadz امة dihukumi Rafa'?","options":["Sebagai Fa'il","Sebagai Mubtada","Sebagai Na'at"],"correct":"Sebagai Fa'il","explanation":"Isim yang marfu' yang disebutkan setelah fi'il-nya disebut sebagai Fa'il."},"9":{"question":"Apa nadhom/syahidnya lafadz امة disebut Rafa'?","options":["الفاعل الذي كمرفوعي أتى || زيد منيرا وجهه نعم الفتى","ورفعوا مبتدأ بالابتدا || كذاك رفع خبر بالمبتدا","فارفع بضم وانصبن فتحا وجر || كسرا كذكر الله عبده يسر"],"correct":"الفاعل الذي كمرفوعي أتى || زيد منيرا وجهه نعم الفتى","explanation":"Bait ini mendefinisikan fa'il sebagai isim yang dibaca rofa' seperti dalam contoh 'Zaidun'."},"10":{"question":"Apa tanda I'rob pada lafadz امة?","options":["Dhammah","Fathah","Alif"],"correct":"Dhammah","explanation":"Tanda rafa' asli bagi isim mufrad adalah dhammah."},"11":{"question":"Mengapa lafadz امة tandanya menggunakan Dhammah?","options":["Karena Isim Mufrad","Karena Jamak Mudzakkar Salim","Karena Asmaul Khomsah"],"correct":"Karena Isim Mufrad","explanation":"Lafadz 'Ummatun' adalah isim tunggal yang tanda rafa'nya menggunakan harakat dhommah zhohirah."},"12":{"question":"apa nadzom/syahidnya lafadz امة itu tandanya menggunakan Dhammah?","options":["فارفع بضم وانصبن فتحا وجر || كسرا كذكر الله عبده يسر","والرفع والنصب اجعلن إعرابا || لاسم وفعل نحو لن أهابا","بالألف ارفع المثنى وكلا || إذا بمضمر مضافا وصلا"],"correct":"فارفع بضم وانصبن فتحا وجر || كسرا كذكر الله عبده يسر","explanation":"Nadzom ini menegaskan bahwa tanda rafa' asli adalah dengan dhommah."}}},{"id_lafadz":"amogenz_lafadz_020","word":"قائد","steps":{"1":{"question":"Apa jenis Lafadz قائد?","options":["Isim","Fi'il","Huruf"],"correct":"Isim","explanation":"Lafadz 'Qaidu' adalah Isim karena menunjukkan profesi/subjek dan dapat menerima tanda isim."},"2":{"question":"Apa tanda/alasan lafadz قائد disebut Isim?","options":["Dapat di-isnad-kan (menjadi Mubtada)","Kemasukan Al","Kemasukan Huruf Jazm"],"correct":"Dapat di-isnad-kan (menjadi Mubtada)","explanation":"Kemampuan menjadi musnad ilaih (subjek dalam jumlah ismiyah) adalah tanda kuat isim."},"3":{"question":"Apa nadhom/syahidnya lafadz قائد disebut Isim?","options":["بالجر والتنوين والندا وأل || ومسند للاسم تمييز حصل","بتا فعلت وأتت ويا افعلي || ونون أقبلن فعل ينجلي","سواهما الحرف كهل وفي ولم || فعل مضارع يلي لم كيشم"],"correct":"بالجر والتنوين والندا وأل || ومسند للاسم تمييز حصل","explanation":"Bait ini menjelaskan 'Musnad' sebagai salah satu penciri isim."},"4":{"question":"Status lafadz قائد itu Mu'rob atau Mabni?","options":["Mu'rob","Mabni"],"correct":"Mu'rob","explanation":"Lafadz ini mu'rob karena tidak menyerupai huruf secara wadh'i, ma'nawi, maupun niyabi."},"5":{"question":"Mengapa lafadz قائد berstatus Mu'rob?","options":["Karena selamat dari penyerupaan dengan huruf","Karena ia Isim Alam","Karena ia Mabni"],"correct":"Karena selamat dari penyerupaan dengan huruf","explanation":"Isim yang selamat dari kemiripan dengan huruf dihukumi mu'rob."},"6":{"question":"Apa nadhom/syahidnya lafadz قائد disebut Mu'rob?","options":["ومعرب الأسماء ما قد سلما || من شبه الحرف كأرض وسما","والاسم منه معرب ومبني || لشبه من الحروف مدني","وكل حرف مستحق للبنا || والأصل في المبني أن يسكنا"],"correct":"ومعرب الأسماء ما قد سلما || من شبه الحرف كأرض وسما","explanation":"Syahid untuk isim mu'rob yang selamat (salima) dari syabah huruf."},"7":{"question":"Apa kedudukan I'rob lafadz قائد?","options":["Rafa'","Nashab","Jarr"],"correct":"Rafa'","explanation":"Lafadz 'Qaidu' berkedudukan sebagai Mubtada (subjek) dalam jumlah ismiyah 'Qaiduha Muhammadun'."},"8":{"question":"Apa alasan lafadz قائد dihukumi Rafa'?","options":["Sebagai Mubtada","Sebagai Fa'il","Sebagai Khabar"],"correct":"Sebagai Mubtada","explanation":"Mubtada adalah isim marfu' yang sepi dari amil lafdzi dan diletakkan di awal kalimat."},"9":{"question":"Apa nadhom/syahidnya lafadz قائد disebut Mubtada?","options":["ورفعوا مبتدأ بالابتدا || كذاك رفع خبر بالمبتدا","الفاعل الذي كمرفوعي أتى || زيد منيرا وجهه نعم الفتى","فارفع بضم وانصبن فتحا وجر || كسرا كذكر الله عبده يسر"],"correct":"ورفعوا مبتدأ بالابتدا || كذاك رفع خبر بالمبتدا","explanation":"Nadzom ini menjelaskan hukum rafa' bagi mubtada dan khobar."},"10":{"question":"Apa tanda I'rob pada lafadz قائد?","options":["Dhammah","Fathah","Kasrah"],"correct":"Dhammah","explanation":"Tanda rafa' isim mufrad adalah dhammah zhohirah."},"11":{"question":"Mengapa lafadz قائد tandanya menggunakan Dhammah?","options":["Karena Isim Mufrad","Karena Jamak Taksir","Karena Asmaul Khomsah"],"correct":"Karena Isim Mufrad","explanation":"Sebagai isim tunggal, tanda i'rob rafa'nya menggunakan dhammah."},"12":{"question":"apa nadzom/syahidnya lafadz قائد itu tandanya menggunakan Dhammah?","options":["فارفع بضم وانصبن فتحا وجر || كسرا كذكر الله عبده يسر","والرفع والنصب اجعلن إعرابا || لاسم وفعل نحو لن أهابا","بالألف ارفع المثنى وكلا || إذا بمضمر مضافا وصلا"],"correct":"فارفع بضم وانصبن فتحا وجر || كسرا كذكر الله عبده يسر","explanation":"Menjelaskan tanda rafa' asli adalah dhammah."}}},{"id_lafadz":"amogenz_lafadz_021","word":"ها","steps":{"1":{"question":"Apa jenis Lafadz ها?","options":["Isim","Fi'il","Huruf"],"correct":"Isim","explanation":"Lafadz 'Ha' adalah Isim Dhomir (kata ganti) yang merujuk pada 'Ummatun'."},"2":{"question":"Apa tanda/alasan lafadz ها disebut Isim?","options":["Dapat menempati posisi Mudhaf Ilaih","Kemasukan Al","Diawali Qad"],"correct":"Dapat menempati posisi Mudhaf Ilaih","explanation":"Hanya isim yang bisa berkedudukan sebagai mudhaf ilaih (penyandar)."},"3":{"question":"Apa nadhom/syahidnya lafadz ها disebut Isim?","options":["بالجر والتنوين والندا وأل || ومسند للاسم تمييز حصل","بتا فعلت وأتت ويا افعلي || ونون أقبلن فعل ينجلي","سواهما الحرف كهل وفي ولم || فعل مضارع يلي لم كيشم"],"correct":"بالجر والتنوين والندا وأل || ومسند للاسم تمييز حصل","explanation":"Ciri isim salah satunya adalah Al-Jarr, dan mudhaf ilaih adalah salah satu sebab i'rob jar."},"4":{"question":"Status lafadz ها itu Mu'rob atau Mabni?","options":["Mu'rob","Mabni"],"correct":"Mabni","explanation":"Semua jenis dhomir adalah mabni."},"5":{"question":"Mengapa lafadz ها berstatus Mabni?","options":["Karena menyerupai huruf secara wadh'i","Karena ia isim isyarah","Karena ia isim mufrad"],"correct":"Karena menyerupai huruf secara wadh'i","explanation":"Dhomir 'Ha' menyerupai huruf dalam segi jumlah susunan hurufnya (hanya dua huruf)."},"6":{"question":"Apa nadhom/syahidnya lafadz ها disebut Mabni?","options":["كالشبه الوضعي في اسمي جئتنا || والمعنوي في متى وفي هنا","والاسم منه معرب ومبني || لشبه من الحروف مدني","وكل حرف مستحق للبنا || والأصل في المبني أن يسكنا"],"correct":"كالشبه الوضعي في اسمي جئتنا || والمعنوي في متى وفي هنا","explanation":"Bait ini menjelaskan syabah wadh'i (seperti pada dhomir) sebagai sebab mabni."},"7":{"question":"Apa kedudukan I'rob lafadz ها?","options":["Jarr","Rafa'","Nashab"],"correct":"Jarr","explanation":"Dhomir yang bersambung dengan isim (Qaid) selalu berkedudukan Jarr sebagai Mudhaf Ilaih."},"8":{"question":"Apa alasan lafadz ها dihukumi Mahal Jarr?","options":["Sebagai Mudhaf Ilaih","Sebagai Fa'il","Sebagai Maf'ul Bih"],"correct":"Sebagai Mudhaf Ilaih","explanation":"Setiap dhomir yang menempel pada isim fungsinya adalah menjelaskan kepemilikan atau penyandaran (idhafah)."},"9":{"question":"Apa nadhom/syahidnya lafadz ها disebut Mudhaf Ilaih?","options":["وإن جرت بكسرة لاسم انتمى || فإنها للجر والمضاف لهما","نونا تلي الإعراب أو تنوينا || مما تضيف احذف كطور سينا","والجر والتنوين والندا وأل || ومسند للاسم تمييز حصل"],"correct":"نونا تلي الإعراب أو تنوينا || مما تضيف احذف كطور سينا","explanation":"Meskipun dhomir mabni, posisinya dalam idhafah menjadikannya mahal jarr."},"10":{"question":"Apa tanda Mabni pada lafadz ها?","options":["Mabni 'ala as-Sukun","Mabni 'ala al-Fath","Mabni 'ala ad-Dhomm"],"correct":"Mabni 'ala as-Sukun","explanation":"Dhomir 'Ha' diakhiri dengan Alif yang merupakan huruf mad (mati/sukun)."},"11":{"question":"Mengapa lafadz ها tandanya menggunakan Sukun?","options":["Karena diakhiri huruf Mad (Alif)","Karena ia Isim Mufrad","Sesuai kaidah i'rob asli"],"correct":"Karena diakhiri huruf Mad (Alif)","explanation":"Isim mabni yang diakhiri alif layyinah dihukumi mabni sukun."},"12":{"question":"apa nadzom/syahidnya lafadz ها itu tandanya menggunakan Sukun?","options":["وكل حرف مستحق للبنا || والأصل في المبني أن يسكنا","ومنه ذو فتح وذو كسر وضم || كأين أمس حيث والساكن كم","فارفع بضم وانصبن فتحا وجر || كسرا كذكر الله عبده يسر"],"correct":"وكل حرف مستحق للبنا || والأصل في المبني أن يسكنا","explanation":"Bait ini menjelaskan bahwa asal kemabnian adalah sukun."}}},{"id_lafadz":"amogenz_lafadz_022","word":"محمد","steps":{"1":{"question":"Apa jenis Lafadz محمد?","options":["Isim","Fi'il","Huruf"],"correct":"Isim","explanation":"Lafadz 'Muhammadun' adalah Isim Alam (nama orang) yang memiliki tanda tanwin."},"2":{"question":"Apa tanda/alasan lafadz محمد disebut Isim?","options":["Adanya Tanwin","Kemasukan Huruf Jazm","Diawali Huruf Mudhara'ah"],"correct":"Adanya Tanwin","explanation":"Tanwin adalah ciri utama dari isim yang tidak dimiliki oleh fi'il maupun huruf."},"3":{"question":"Apa nadhom/syahidnya lafadz محمد disebut Isim?","options":["بالجر والتنوين والندا وأل || ومسند للاسم تمييز حصل","بتا فعلت وأتت ويا افعلي || ونون أقبلن فعل ينجلي","سواهما الحرف كهل وفي ولم || فعل مضارع يلي لم كيشم"],"correct":"بالجر والتنوين والندا وأل || ومسند للاسم تمييز حصل","explanation":"Menyebutkan tanwin sebagai salah satu tanda isim."},"4":{"question":"Status lafadz محمد itu Mu'rob atau Mabni?","options":["Mu'rob","Mabni"],"correct":"Mu'rob","explanation":"Isim alam ini mu'rob karena tidak menyerupai huruf."},"5":{"question":"Mengapa lafadz محمد berstatus Mu'rob?","options":["Karena selamat dari penyerupaan dengan huruf","Karena ia Isim Mufrad","Karena ia nama Nabi"],"correct":"Karena selamat dari penyerupaan dengan huruf","explanation":"Asal isim adalah mu'rob selama tidak ada faktor yang menyerupakannya dengan huruf."},"6":{"question":"Apa nadhom/syahidnya lafadz محمد disebut Mu'rob?","options":["ومعرب الأسماء ما قد سلما || من شبه الحرف كأرض وسما","والاسم منه معرب ومبني || لشبه من الحروف مدني","وكل حرف مستحق للبنا || والأصل في المبني أن يسكنا"],"correct":"ومعرب الأسماء ما قد سلما || من شبه الحرف كأرض وسما","explanation":"Bait ini menjelaskan syarat isim mu'rob."},"7":{"question":"Apa kedudukan I'rob lafadz محمد?","options":["Rafa'","Nashab","Jarr"],"correct":"Rafa'","explanation":"Lafadz 'Muhammadun' berkedudukan sebagai Khabar (predikat) bagi mubtada 'Qaid'."},"8":{"question":"Apa alasan lafadz محمد dihukumi Rafa'?","options":["Sebagai Khabar","Sebagai Mubtada","Sebagai Na'at"],"correct":"Sebagai Khabar","explanation":"Khabar adalah bagian yang menyempurnakan makna mubtada dan hukumnya adalah rafa'."},"9":{"question":"Apa nadhom/syahidnya lafadz محمد disebut Khabar?","options":["ورفعوا مبتدأ بالابتدا || كذاك رفع خبر بالمبتدا","الفاعل الذي كمرفوعي أتى || زيد منيرا وجهه نعم الفتى","والخبر الجزء المتم الفائدة || كالله بر والايادي شاهدة"],"correct":"والخبر الجزء المتم الفائدة || كالله بر والايادي شاهدة","explanation":"Nadzom ini mendefinisikan khabar sebagai penyempurna faidah kalimat."},"10":{"question":"Apa tanda I'rob pada lafadz محمد?","options":["Dhammah","Fathah","Wawu"],"correct":"Dhammah","explanation":"Tanda rafa' asli bagi isim mufrad adalah dhammah."},"11":{"question":"Mengapa lafadz محمد tandanya menggunakan Dhammah?","options":["Karena Isim Mufrad","Karena Jamak Taksir","Karena Isim Ghairu Munsharif"],"correct":"Karena Isim Mufrad","explanation":"Lafadz ini adalah tunggal (mufrad) sehingga tanda rafa'nya adalah dhommah."},"12":{"question":"apa nadzom/syahidnya lafadz محمد itu tandanya menggunakan Dhammah?","options":["فارفع بضم وانصبن فتحا وجر || كسرا كذكر الله عبده يسر","والرفع والنصب اجعلن إعرابا || لاسم وفعل نحو لن أهابا","اجعل لنحو يفعلان نونا || رفعهما وتدعين وتسالونا"],"correct":"فارفع بضم وانصبن فتحا وجر || كسرا كذكر الله عبده يسر","explanation":"Menjelaskan tanda-tanda i'rob asli."}}}]},{"id_kalimat":"amogenz_kalimat_006","teks_kalimat":"رز غبا تزدد حبا","analysis":[{"id_lafadz":"amogenz_lafadz_023","word":"زر","steps":{"1":{"question":"Apa jenis Lafadz زر?","options":["Isim","Fi'il","Huruf"],"correct":"Fi'il","explanation":"Lafadz 'Zur' adalah Fi'il Amr (kata kerja perintah) karena mengandung makna tuntutan dan dapat menerima Nun Taukid."},"2":{"question":"Apa tanda/alasan lafadz زر disebut Fi'il?","options":["Menunjukkan perintah dan menerima Ya' Mukhatabah","Kemasukan Al","Menerima Tanwin"],"correct":"Menunjukkan perintah dan menerima Ya' Mukhatabah","explanation":"Ciri khas Fi'il Amr adalah menunjukkan tholab (permintaan) serta layak bersambung dengan Ya' Mukhatabah (seperti 'Zuurii')."},"3":{"question":"Apa nadhom/syahidnya lafadz زر disebut Fi'il?","options":["بتا فعلت وأتت ويا افعلي || ونون أقبلن فعل ينجلي","سواهما الحرف كهل وفي ولم || فعل مضارع يلي لم كيشم","بالجر والتنوين والندا وأل || ومسند للاسم تمييز حصل"],"correct":"بتا فعلت وأتت ويا افعلي || ونون أقبلن فعل ينجلي","explanation":"Bait ini menjelaskan tanda-tanda fi'il secara umum, termasuk Ya' Mukhatabah (Ya' If'ali) dan Nun Taukid (Nun Aqbilan)."},"4":{"question":"Status lafadz زر itu Mu'rob atau Mabni?","options":["Mu'rob","Mabni"],"correct":"Mabni","explanation":"Fi'il Amr dihukumi Mabni (permanen akhirnya) menurut pendapat yang kuat (Madzhab Bashrah) yang diikuti Ibnu Malik."},"5":{"question":"Mengapa lafadz زر berstatus Mabni?","options":["Karena merupakan Fi'il Amr","Karena menyerupai huruf","Karena tidak ada amil"],"correct":"Karena merupakan Fi'il Amr","explanation":"Semua Fi'il Amr adalah mabni, berbeda dengan Fi'il Mudhari yang asalnya adalah mu'rob."},"6":{"question":"Apa nadhom/syahidnya lafadz زر disebut Mabni?","options":["وفعل أمر ومضي بنيا || وأعربوا مضارعا إن عريا","والاسم منه معرب ومبني || لشبه من الحروف مدني","وكل حرف مستحق للبنا || والأصل في المبني أن يسكنا"],"correct":"وفعل أمر ومضي بنيا || وأعربوا مضارعا إن عريا","explanation":"Bait ini secara tegas menyatakan bahwa fi'il amr dan madhi itu mabni (buniya)."},"7":{"question":"Apa kedudukan I'rob/Mabni lafadz زر?","options":["Mabni 'ala as-Sukun","Mabni 'ala al-Fath","Mabni 'ala Hadzfi an-Nun"],"correct":"Mabni 'ala as-Sukun","explanation":"Lafadz 'Zur' mabni atas sukun karena ia fi'il amr yang shahih akhir dan tidak bersambung dengan sesuatu di akhirnya."},"8":{"question":"Apa alasan lafadz زر dihukumi Mabni 'ala as-Sukun?","options":["Karena Shahih Akhir dan tidak bersambung dengan sesuatu","Karena Isim Mufrad","Karena kemasukan amil jazm"],"correct":"Karena Shahih Akhir dan tidak bersambung dengan sesuatu","explanation":"Fi'il amr dimabnikan atas tanda jazm mudhari-nya; karena mudhari-nya (tazuuru) dijazmkan dengan sukun, maka amr-nya pun mabni sukun."},"9":{"question":"Apa nadhom/syahidnya lafadz زر disebut Mabni 'ala as-Sukun?","options":["والأصل في المبني أن يسكنا || ومنه ذو فتح وذو كسر وضم","فارفع بضم وانصبن فتحا وجر || كسرا كذكر الله عبده يسر","واجزم بتسكين وغير ما ذكر || ينوب نحو جا اخو بنى نمر"],"correct":"والأصل في المبني أن يسكنا || ومنه ذو فتح وذو كسر وضم","explanation":"Bait ini menerangkan bahwa asal dari hukum mabni adalah sukun."},"10":{"question":"Apa tanda Mabni pada lafadz زر?","options":["Sukun","Fathah","Hadzfu al-Akhir"],"correct":"Sukun","explanation":"Huruf terakhir (Ra') dibaca mati atau sukun."},"11":{"question":"Mengapa lafadz زر tandanya menggunakan Sukun?","options":["Karena merupakan tanda asli kemabnian","Karena ia mu'rob","Karena jamak taksir"],"correct":"Karena merupakan tanda asli kemabnian","explanation":"Sesuai kaidah bahwa asal dari bangunan kalimat (mabni) adalah sukun selama tidak ada sebab untuk berharakat."},"12":{"question":"apa nadzom/syahidnya lafadz زر itu tandanya menggunakan Sukun?","options":["والأصل في المبني أن يسكنا || ومنه ذو فتح وذو كسر وضم","فارفع بضم وانصبن فتحا وجر || كسرا كذكر الله عبده يسر","وكل حرف مستحق للبنا || والأصل في المبني أن يسكنا"],"correct":"والأصل في المبني أن يسكنا || ومنه ذو فتح وذو كسر وضم","explanation":"Ibnu Malik menyebutkan bahwa pokok dari mabni adalah disukunkan."}}},{"id_lafadz":"amogenz_lafadz_024","word":"غبا","steps":{"1":{"question":"Apa jenis Lafadz غبا?","options":["Isim","Fi'il","Huruf"],"correct":"Isim","explanation":"Lafadz 'Ghibban' adalah Isim karena menunjukkan keterangan waktu (Zharf) dan menerima tanwin."},"2":{"question":"Apa tanda/alasan lafadz غبا disebut Isim?","options":["Adanya Tanwin","Adanya Al","Adanya Ta' Marbuthoh"],"correct":"Adanya Tanwin","explanation":"Tanda fisik yang nampak pada lafadz 'Ghibban' adalah adanya harakat tanwin di akhirnya."},"3":{"question":"Apa nadhom/syahidnya lafadz غبا disebut Isim?","options":["بالجر والتنوين والندا وأل || ومسند للاسم تمييز حصل","بتا فعلت وأتت ويا افعلي || ونون أقبلن فعل ينجلي","سواهما الحرف كهل وفي ولم || فعل مضارع يلي لم كيشم"],"correct":"بالجر والتنوين والندا وأل || ومسند للاسم تمييز حصل","explanation":"Tanwin disebutkan secara eksplisit sebagai salah satu tanda khusus isim dalam bait ini."},"4":{"question":"Status lafadz غبا itu Mu'rob atau Mabni?","options":["Mu'rob","Mabni"],"correct":"Mu'rob","explanation":"Isim ini mu'rob karena tidak menyerupai huruf dan dapat berubah harakat akhirnya sesuai kedudukan."},"5":{"question":"Mengapa lafadz غبا berstatus Mu'rob?","options":["Selamat dari penyerupaan dengan huruf","Karena ia Zharf","Karena ia Isim Mufrad"],"correct":"Selamat dari penyerupaan dengan huruf","explanation":"Isim yang 'salim' (selamat) dari kemiripan dengan huruf dihukumi mu'rob."},"6":{"question":"Apa nadhom/syahidnya lafadz غبا disebut Mu'rob?","options":["ومعرب الأسماء ما قد سلما || من شبه الحرف كأرض وسما","والاسم منه معرب ومبني || لشبه من الحروف مدني","وكل حرف مستحق للبنا || والأصل في المبني أن يسكنا"],"correct":"ومعرب الأسماء ما قد سلما || من شبه الحرف كأرض وسما","explanation":"Bait ini menjelaskan definisi isim mu'rob."},"7":{"question":"Apa kedudukan I'rob lafadz غبا?","options":["Nashab","Rafa'","Jarr"],"correct":"Nashab","explanation":"Lafadz 'Ghibban' dibaca nashab karena berkedudukan sebagai Zharf Zaman (Maf'ul Fih)."},"8":{"question":"Apa alasan lafadz غبا dihukumi Nashab?","options":["Sebagai Maf'ul Fih (Zharf Zaman)","Sebagai Maf'ul Bih","Sebagai Hal"],"correct":"Sebagai Maf'ul Fih (Zharf Zaman)","explanation":"Ghibban menunjukkan keterangan waktu ('jarang-jarang') yang menyimpan makna 'fii' (di dalam/pada waktu)."},"9":{"question":"Apa nadhom/syahidnya lafadz غبا disebut Zharf?","options":["الظرف وقت أو مكان ضمنا || في باطراد كهنا امكث أزمنا","فانصب به المفعول إن لم ينب || عن فاعل نحو تدبرت الكتبي","والرفع والنصب اجعلن إعرابا || لاسم وفعل نحو لن أهابا"],"correct":"الظرف وقت أو مكان ضمنا || في باطراد كهنا امكث أزمنا","explanation":"Bait ini mendefinisikan Zharf sebagai keterangan waktu atau tempat yang mengandung makna 'fii'."},"10":{"question":"Apa tanda I'rob pada lafadz غبا?","options":["Fathah","Dhammah","Kasrah"],"correct":"Fathah","explanation":"Tanda nashab asli bagi isim mufrad adalah fathah zhohirah."},"11":{"question":"Mengapa lafadz غبا tandanya menggunakan Fathah?","options":["Karena Isim Mufrad","Karena Jamak Taksir","Karena Af'alul Khomsah"],"correct":"Karena Isim Mufrad","explanation":"Lafadz 'Ghibban' adalah kata tunggal (mufrad) sehingga menggunakan tanda i'rob asli."},"12":{"question":"apa nadzom/syahidnya lafadz غبا itu tandanya menggunakan Fathah?","options":["فارفع بضم وانصبن فتحا وجر || كسرا كذكر الله عبده يسر","والرفع والنصب اجعلن إعرابا || لاسم وفعل نحو لن أهابا","واجزم بتسكين وغير ما ذكر || ينوب نحو جا اخو بنى نمر"],"correct":"فارفع بضم وانصبن فتحا وجر || كسرا كذكر الله عبده يسر","explanation":"Bait ini menjelaskan tanda-tanda i'rob asli (Rafa' dhommah, Nashab fathah, Jarr kasrah)."}}},{"id_lafadz":"amogenz_lafadz_025","word":"تزدد","steps":{"1":{"question":"Apa jenis Lafadz تزدد?","options":["Isim","Fi'il","Huruf"],"correct":"Fi'il","explanation":"Lafadz 'Tazdad' adalah Fi'il Mudhari karena diawali huruf mudhara'ah 'Ta' dan menunjukkan proses bertambahnya sesuatu."},"2":{"question":"Apa tanda/alasan lafadz تزدد disebut Fi'il?","options":["Bisa diawali amil Jazm (Lam) dan menunjukkan waktu","Kemasukan Al","Menerima Tanwin"],"correct":"Bisa diawali amil Jazm (Lam) dan menunjukkan waktu","explanation":"Kriteria fi'il mudhari adalah kelayakannya mengikuti huruf jazm 'Lam' (Lam Tazdad)."},"3":{"question":"Apa nadhom/syahidnya lafadz تزدد disebut Fi'il?","options":["سواهما الحرف كهل وفي ولم || فعل مضارع يلي لم كيشم","بتا فعلت وأتت ويا افعلي || ونون أقبلن فعل ينجلي","بالجر والتنوين والندا وأل || ومسند للاسم تمييز حصل"],"correct":"سواهما الحرف كهل وفي ولم || فعل مضارع يلي لم كيشم","explanation":"Nadzom ini menjelaskan bahwa mudhari adalah fi'il yang bisa diawali oleh Lam."},"4":{"question":"Status lafadz تزدد itu Mu'rob atau Mabni?","options":["Mu'rob","Mabni"],"correct":"Mu'rob","explanation":"Fi'il mudhari ini mu'rob karena tidak bersambung dengan Nun Taukid maupun Nun Inats."},"5":{"question":"Mengapa lafadz تزدد berstatus Mu'rob?","options":["Sepi dari Nun Taukid dan Nun Inats","Karena diawali huruf mudhara'ah","Karena ia Jawabul Thalab"],"correct":"Sepi dari Nun Taukid dan Nun Inats","explanation":"Mudhari baru menjadi mabni jika bersambung langsung dengan nun-nun tersebut."},"6":{"question":"Apa nadhom/syahidnya lafadz تزدد disebut Mu'rob?","options":["وأعربوا مضارعا إن عريا || من نون توكيد مباشر ومن || نون إناث كيرعن من فتن","وفعل أمر ومضي بنيا || وأعربوا مضارعا إن عريا","والاسم منه معرب ومبني || لشبه من الحروف مدني"],"correct":"وأعربوا مضارعا إن عريا || من نون توكيد مباشر ومن || نون إناث كيرعن من ften","explanation":"Ibnu Malik merinci syarat kemu'rob-an mudhari dalam bait ini."},"7":{"question":"Apa kedudukan I'rob lafadz تزدد?","options":["Jazm","Rafa'","Nashab"],"correct":"Jazm","explanation":"Fi'il mudhari ini dijazmkan karena berkedudukan sebagai Jawabul Thalab (jawaban dari perintah 'Zur')."},"8":{"question":"Apa alasan lafadz تزدد dihukumi Jazm?","options":["Jatuh setelah Thalab (Perintah)","Didahului huruf Jazm Lam","Sebagai Fi'il Syarat"],"correct":"Jatuh setelah Thalab (Perintah)","explanation":"Dalam kaidah nahwu, mudhari yang menjadi hasil/konsekuensi dari perintah sebelumnya (Zur) dibaca jazm."},"9":{"question":"Apa nadhom/syahidnya lafadz تزدد disebut Jazm?","options":["وجزموا بوقع فعل بعد طلب || إن كان معنى إن له قد استحب","ارفع مضارعا إذا يجرد || من ناصب وجازم كتسعد","واجزم بتسكين وغير ما ذكر || ينوب نحو جا اخو بنى نمر"],"correct":"وجزموا بوقع فعل بعد طلب || إن كان معنى إن له قد استحب","explanation":"Bait ini menjelaskan tentang jazm-nya fi'il yang terletak setelah tholab (perintah/permintaan)."},"10":{"question":"Apa tanda I'rob pada lafadz تزدد?","options":["Sukun","Hadzfu al-Akhir","Hadzfu an-Nun"],"correct":"Sukun","explanation":"Tanda jazm-nya adalah sukun zhohir pada huruf terakhir (Dal)."},"11":{"question":"Mengapa lafadz تزدد tandanya menggunakan Sukun?","options":["Karena Fi'il Mudhari Shahih Akhir","Karena Af'alul Khomsah","Karena Isim Mufrad"],"correct":"Karena Fi'il Mudhari Shahih Akhir","explanation":"Karena huruf akhirnya (Dal) bukan huruf illat, maka tanda jazm-nya adalah sukun asli."},"12":{"question":"apa nadzom/syahidnya lafadz تزدد itu tandanya menggunakan Sukun?","options":["واجزم بتسكين وغير ما ذكر || ينوب نحو جا اخو بنى نمر","فارفع بضم وانصبن فتحا وجر || كسرا كذكر الله عبده يسر","وكل حرف مستحق للبنا || والأصل في المبني أن يسكنا"],"correct":"واجزم بتسكين وغير ما ذكر || ينوب نحو جا اخو بنى نمر","explanation":"Nadzom ini menjelaskan bahwa tanda i'rob jazm yang utama adalah sukun (taskiin)."}}},{"id_lafadz":"amogenz_lafadz_026","word":"حبا","steps":{"1":{"question":"Apa jenis Lafadz حبا?","options":["Isim","Fi'il","Huruf"],"correct":"Isim","explanation":"Lafadz 'Hubban' adalah Isim karena menunjukkan nama perasaan/benda abstrak dan menerima tanwin."},"2":{"question":"Apa tanda/alasan lafadz حبا disebut Isim?","options":["Adanya Tanwin","Kemasukan Al","Kemasukan Qad"],"correct":"Adanya Tanwin","explanation":"Tanwin di akhir kata 'Hubban' memastikan bahwa kata tersebut adalah isim."},"3":{"question":"Apa nadhom/syahidnya lafadz حبا disebut Isim?","options":["بالجر والتنوين والندا وأل || ومسند للاسم تمييز حصل","بتا فعلت وأتت ويا افعلي || ونون أقبلن فعل ينجلي","سواهما الحرف كهل وفي ولم || فعل مضارع يلي لم كيشم"],"correct":"بالجر والتنوين والندا وأل || ومسند للاسم تمييز حصل","explanation":"Syahid untuk ciri isim berupa tanwin."},"4":{"question":"Status lafadz حبا itu Mu'rob atau Mabni?","options":["Mu'rob","Mabni"],"correct":"Mu'rob","explanation":"Isim mufrad ini mu'rob karena tidak ada alasan untuk dimabnikan (tidak mirip huruf)."},"5":{"question":"Mengapa lafadz حبا berstatus Mu'rob?","options":["Selamat dari penyerupaan dengan huruf","Karena ia Tamyiz","Karena ia Isim Mashdar"],"correct":"Selamat dari penyerupaan dengan huruf","explanation":"Syarat mu'rob bagi isim adalah terbebas dari kemiripan fungsional, makna, atau posisi dengan huruf."},"6":{"question":"Apa nadhom/syahidnya lafadz حبا disebut Mu'rob?","options":["ومعرب الأسماء ما قد سلما || من شبه الحرف كأرض وسما","والاسم منه معرب ومبني || لشبه من الحروف مدني","وكل حرف مستحق للبنا || والأصل في المبني أن يسكنا"],"correct":"ومعرب الأسماء ما قد سلما || من شبه الحرف كأرض وسما","explanation":"Bait ini mendasari hukum mu'rob bagi isim-isim yang 'salim'."},"7":{"question":"Apa kedudukan I'rob lafadz حبا?","options":["Nashab","Rafa'","Jarr"],"correct":"Nashab","explanation":"Lafadz 'Hubban' dibaca nashab karena berkedudukan sebagai Tamyiz."},"8":{"question":"Apa alasan lafadz حبا dihukumi Nashab?","options":["Sebagai Tamyiz","Sebagai Maf'ul Bih","Sebagai Maf'ul Mutlaq"],"correct":"Sebagai Tamyiz","explanation":"Hubban menjelaskan sisi ketidakjelasan (keumuman) dari bertambahnya sesuatu pada fi'il 'Tazdad' (bertambah dalam hal apa? bertambah cinta)."},"9":{"question":"Apa nadhom/syahidnya lafadz حبا disebut Tamyiz?","options":["اسم بمعنى من مبين نكره || ينصب تمييزا بما قد فسره","فانصب به المفعول إن لم ينب || عن فاعل نحو تدبرت الكتبي","الحال وصف فضلة منتصب || مفهم في حال كفردا أذهب"],"correct":"اسم بمعنى من مبين نكره || ينصب تمييزا بما قد فسره","explanation":"Bait ini mendefinisikan tamyiz sebagai isim nakiroh penjelas yang bermakna 'min'."},"10":{"question":"Apa tanda I'rob pada lafadz حبا?","options":["Fathah","Dhammah","Ya'"],"correct":"Fathah","explanation":"Isim mufrad dalam keadaan nashab menggunakan tanda fathah zhohirah."},"11":{"question":"Mengapa lafadz حبا tandanya menggunakan Fathah?","options":["Karena Isim Mufrad","Karena Jamak Taksir","Karena Fi'il Madhi"],"correct":"Karena Isim Mufrad","explanation":"Sebagai kata tunggal, 'Hubban' mengikuti hukum i'rob asli."},"12":{"question":"apa nadzom/syahidnya lafadz حبا itu tandanya menggunakan Fathah?","options":["فارفع بضم وانصبن فتحا وجر || كسرا كذكر الله عبده يسر","والرفع والنصب اجعلن إعرابا || لاسم وفعل نحو لن أهابا","واجزم بتسكين وغير ما ذكر || ينوب نحو جا اخو بنى نمر"],"correct":"فارفع بضم وانصبن فتحا وجر || كسرا كذكر الله عبده يسر","explanation":"Menjelaskan tanda nashab asli adalah fathah."}}}]}];
